`timescale 1ns/1ps
// Auto-generated by autombist from config.yml: a BEHAVIORAL model of the memory,
// writes on the rising edge, reads one clock after the registered access, data held until the next read (read_latency 1).
// Idealized: fault-free, no timing checks, contents power up unknown. It is NOT the
// macro's own model; pass that model to run_tb.sh to replace this one.
module sram_x #(
    parameter integer ADDR_WIDTH = 4,
    parameter integer DATA_WIDTH = 8,
    parameter integer NUM_SPARE_ROWS = 0,
    parameter integer NUM_SPARE_COLS = 0
) (
    input  wire clk0,
    input  wire csb0,
    input  wire web0,
    input  wire [3:0] addr0,
    input  wire [7:0] din0,
    output reg  [7:0] dout0
);
    // The wrapper overrides the parameters above; the widths below are the ones it connects.
    localparam integer LOGICAL_W = 8;
    localparam integer DEPTH = 16;
    reg [7:0] mem [0:DEPTH-1];

    // port 0: rw
    reg p0_csb_q;
    reg [3:0] p0_addr_q;
